    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def idiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                val = idiv(val, rhs)
        return val

    def parse_factor():
        neg = False
        while peek() == '-':
            advance()
            neg = not neg
        # handle unary plus too, just in case, though not specified
        while peek() == '+':
            advance()
        val = parse_primary()
        if neg:
            val = -val
        return val

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            if peek() == ')':
                advance()
            return val
        else:
            advance()
            return int(tok)

    result = parse_expr()
    return result

